  /* ---------- Unit 8: Insurance ---------- */
  var PLAN = { A: { premium: 310, deductible: 500, coinsurance: 0.10, oopMax: 3000, copay: 20 }, B: { premium: 210, deductible: 2000, coinsurance: 0.20, oopMax: 6000, copay: 35 }, C: { premium: 95, deductible: 6000, coinsurance: 0.20, oopMax: 8000, copay: 0 } };
